const schema = {
    type: "object",
    properties: {
        userId: { type: "number" },
        id: { type: "number" },
        title: { type: "string" },
        body: { type: "string" }
    },
    required: ["userId", "id", "title", "body"]
};

let response = pm.response.json()

pm.test("Status code es 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Payload is valid", function (){
    pm.expect(response).to.have.property("userId").that.is.a("number")
    pm.expect(response.userId).to.be.a("number")
})

pm.test("Schema is valid", function () {
    pm.response.to.have.jsonSchema(schema);
});

pm.collectionVariables.set("userId",response.userId)

const schema = {
    type: "object",
    properties: {
        id: { type: "number" },
        username: { type: "string"},
        email: { type: "string"},
        address: { 
            type: "object",
            properties: {
                street: { type: "string" },
                suite: { type: "string" },
                city: { type: "string" },
                zipcode: { type: "string" },
                geo: {
                    type: "object",
                    properties: {
                        lat: { type: "string" },
                        lng: { type: "string" }
                    },
                    required: ["lat", "lng"]
                }
            },
            required: ["street", "suite", "city", "zipcode", "geo"]
        },
        phone: { type: "string" },
        website: { type: "string" },
        company: {
            type: "object",
            properties: {
                "name": { type: "string" },
                "catchPhrase": { type: "string" },
                "bs": { type: "string" }
            },
            require: ["name", "catchPhrase", "bs"]
        },
    },
    required: ["id", "username", "email", "address", "phone", "website", "company"]
};

let response = pm.response.json()

pm.test("Status code es 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Payload is valid", function (){
    pm.expect(response).to.have.property("name").that.is.a("string")
    pm.expect(response.name).to.be.a("string")
})

pm.test("Schema is valid", function () {
    pm.response.to.have.jsonSchema(schema);
});
